import{_ as e,o,c as n,ag as i}from"./chunks/plugin-vue_export-helper.BT7B-090.js";const u=JSON.parse('{"title":"Лучшие промышленные практики построения AI-агентов, 1 из 10","description":"","frontmatter":{"site":"pro","title":"Лучшие промышленные практики построения AI-агентов, 1 из 10","date":"2026-10-04T00:00:00.000Z","source":"https://t.me/jfyi_ps/93","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-10-04-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-1"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Лучшие промышленные практики построения AI-агентов, 1 из 10"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-10-04-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-1"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Лучшие промышленные практики построения AI-агентов, 1 из 10"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"Лучшие промышленные практики построения AI-агентов, 1 из 10\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-10-04-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-1\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-10-04\\"}"]]},"headers":[],"relativePath":"posts/2026-10-04-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-1.md","filePath":"posts/2026-10-04-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-1.md"}'),r={name:"posts/2026-10-04-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-1.md"};function s(p,t,a,l,g,c){return o(),n("div",null,[...t[0]||(t[0]=[i("<p>Выжимка из книги Ли Боцзе «Глубокое понимание AI Agent: принципы проектирования и инженерная практика» (Pine AI, v2.0, 2026).</p><p>Формула-ядро: <strong>Агент = LLM (мозг) + Контекст (глаза) + Инструменты (руки-ноги)</strong>; в продакшн-форме: <strong>Агент = Model + Harness</strong>, где Harness = управление контекстом + интерфейсы инструментов + <strong>ограничения + проверка + исправление</strong>.</p><p><strong>1. Основы и Harness-инженерия</strong></p><p>Вводи агентность только когда задача требует автономного выбора пути решения на каждом шаге — она с задержкой и стоимостью. Если порядок шагов и условия перехода известны — это workflow. Подробнее о применимости мультиагентного подхода - в части 10.</p><p>Оценивай модель на своей задаче, не по рейтингам: точность/цена/скорость + согласится ли модель выполнять задачу (политики) + хватает ли API. Для многошаговых решений нужен reasoning.</p><p>Менять модель дорого, лучше расширять контекст и инструменты, а не ждать модель умнее.</p><p>Основная масса продакшн-кода — ограничения/проверки/исправление, а не сами контекст/инструменты.</p><p>Три принципа эффективного агента: простота (API &gt; фреймворк), прозрачность (видимые логи/траектория), хороший ACI (интерфейс инструментов с т.з. агента).</p><p>В коде закрепляй только нерушимые границы (права, запрет перезаписи, атомарная публикация); остальное — пространство решений модели. Отдельный верификатор — только когда бизнес-ограничение или устойчивый паттерн сбоя этого требует.</p><p>Всегда задавай явные условия остановки (успех/final_answer/нет вызова/лимит ошибок/лимит раундов); гоняй в песочнице с мониторингом и человеко-точками перед продакшном.</p><p>Фреймворк выбирай по тому, не мешает ли он сосредоточиться на бизнес-логике — API фреймворков быстро устаревает.</p><p><strong>Ограждения (3 слоя по трудности обхода):</strong></p><ul><li>контекст (классификатор jailbreak/injection, модерация, regex),</li><li>исполнение (риск-оценка инструмента; отдельный процесс/sandbox/человек; проверка смотрит только на структурные поля, не на текст модели)</li><li>данные (RLS, валидаторы, недоступный агенту контекст доступа — отвергнет операцию даже если injection прошла).</li></ul><p><strong>5 сквозных паттернов:</strong></p><ul><li>Proposer-Reviewer (проверяющий не делит контекст с производителем, видит только артефакт);</li><li>Progressive Disclosure (от общего к частному);</li><li>Append-only (кэшируемость/аудит);</li><li>граничный+удерживающий набор;</li><li>минимальный diff + обратимость.</li></ul><p><strong>3 горизонта обновления:</strong></p><ul><li>контекст (мс, временно)</li><li>внешние артефакты: знания/Prompt/Skill/Harness (проверяемо, между задачами)</li><li>параметры модели (дорого, недели, для стиля/неявной стратегии/восприятия).</li></ul><p>Продолжение следует...</p>",18)])])}const h=e(r,[["render",s]]);export{u as __pageData,h as default};
